window.docContents[205].resolve({"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Inductively-Defined-Propositions":{"contents":"In the Logic chapter, we looked at several ways of writing\npropositions, including conjunction, disjunction, and existential\nquantification.\n\nIn this chapter, we bring yet another new tool into the mix:\ninductively defined propositions.\n\nTo begin, some examples...\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Logical Foundations\u0009IndProp: Inductively Defined Propositions","header":"8.1. Inductively Defined Propositions","id":"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Inductively-Defined-Propositions"}});